WITH DeptStats2022 AS ( WITH inner_cte AS ( SELECT SIS_COURSE_DESCRIPTION.DEPARTMENT_NAME, COURSE_CATALOG_SUBJECT_OFFERED.TOTAL_UNITS FROM SIS_SUBJECT_CODE JOIN SIS_COURSE_DESCRIPTION ON SIS_SUBJECT_CODE.COURSE_NUMBER = SIS_COURSE_DESCRIPTION.COURSE JOIN COURSE_CATALOG_SUBJECT_OFFERED ON SIS_COURSE_DESCRIPTION.COURSE = COURSE_CATALOG_SUBJECT_OFFERED.SUBJECT_CODE WHERE COURSE_CATALOG_SUBJECT_OFFERED.ACADEMIC_YEAR = 2022 AND SIS_COURSE_DESCRIPTION.IS_DEGREE_GRANTING = 'Y' ) SELECT inner_cte.DEPARTMENT_NAME, COUNT(*) AS subject_count, AVG(inner_cte.TOTAL_UNITS) AS avg_total_units, MAX(inner_cte.TOTAL_UNITS) - MIN(inner_cte.TOTAL_UNITS) AS total_units_range, VARIANCE(inner_cte.TOTAL_UNITS) AS total_units_variance FROM inner_cte GROUP BY inner_cte.DEPARTMENT_NAME HAVING COUNT(*) >= 5 ), LibResMatrlStats AS ( WITH inner_cte AS ( SELECT ACADEMIC_TERMS_ALL.ACADEMIC_YEAR, ACADEMIC_TERMS_ALL.ACADEMIC_YEAR_DESC, COURSE_CATALOG_SUBJECT_OFFERED.DEPARTMENT_NAME, COURSE_CATALOG_SUBJECT_OFFERED.TOTAL_UNITS FROM LIBRARY_RESERVE_MATRL_DETAIL JOIN ACADEMIC_TERMS_ALL ON LIBRARY_RESERVE_MATRL_DETAIL.TERM_CODE = ACADEMIC_TERMS_ALL.TERM_CODE JOIN COURSE_CATALOG_SUBJECT_OFFERED ON ACADEMIC_TERMS_ALL.TERM_CODE = COURSE_CATALOG_SUBJECT_OFFERED.TERM_CODE WHERE LIBRARY_RESERVE_MATRL_DETAIL.LIBRARY_MATERIAL_STATUS_KEY = 'U' ) SELECT inner_cte.ACADEMIC_YEAR, inner_cte.ACADEMIC_YEAR_DESC, inner_cte.DEPARTMENT_NAME, STDDEV(inner_cte.TOTAL_UNITS)/NULLIF(AVG(inner_cte.TOTAL_UNITS),0) AS coefficient_of_variation FROM inner_cte GROUP BY inner_cte.ACADEMIC_YEAR, inner_cte.ACADEMIC_YEAR_DESC, inner_cte.DEPARTMENT_NAME HAVING AVG(inner_cte.TOTAL_UNITS) > 0 ), CombinedStats AS ( SELECT d.DEPARTMENT_NAME, NULL AS ACADEMIC_YEAR, NULL AS ACADEMIC_YEAR_DESC, d.subject_count, d.avg_total_units, d.total_units_range, d.total_units_variance, NULL AS coefficient_of_variation, '2022 Degree-Granting Subjects' AS Reason FROM DeptStats2022 d UNION ALL SELECT l.DEPARTMENT_NAME, l.ACADEMIC_YEAR, l.ACADEMIC_YEAR_DESC, NULL AS subject_count, NULL AS avg_total_units, NULL AS total_units_range, NULL AS total_units_variance, l.coefficient_of_variation, 'Library Reserve Materials' AS Reason FROM LibResMatrlStats l ) SELECT * FROM CombinedStats ORDER BY DEPARTMENT_NAME, Reason;